import{z as s,x as d,o as t,c as p,q as o,j as B,D as e,d as i,s as l,S as r,b as E}from"./chunks/framework.C8m1ZpeB.js";const c=JSON.parse('{"title":"单调队列优化","description":"","frontmatter":{"title":"单调队列优化","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/monotone-queue-opt.md","filePath":"cs/monotone-queue-opt.md","lastUpdated":1791413859000}'),A={name:"cs/monotone-queue-opt.md"};function m(u,a,P,h,C,D){const n=d("Mermaid");return t(),p("div",null,[a[2]||(a[2]=o('<h1 id="单调队列优化" tabindex="-1">单调队列优化 <a class="header-anchor" href="#单调队列优化" aria-label="Permalink to &quot;单调队列优化&quot;">​</a></h1><div class="epigraph"><p>转移 $dp[i]=\\min_{j\\in[i-w,i)} (dp[j]+c[j])$ 且候选随 $i$ 滑动时，队头过期、队尾维护单调，均摊 $O(1)$ 转移。</p><footer>—— 据 Knuth TAOCP 与滑动窗口最小值；CLRS 第 15 章 DP 整理</footer></div><p>上一课<a href="/cs/digit-dp">数位 DP</a>沿位数。数值 DP 常 \\(O(n^2)\\) 枚举切点。缺口是窗口内最值：单调队列（deque）维护下标递增、键单调。不重写数位自动机。后课斜率优化窗口变成凸包。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>\\(dp[i]=\\min_{i-w\\le j\\lt i} dp[j]+b[i]\\)（\\(b\\) 与 \\(j\\) 无关）即滑动 \\(\\min\\)。队头弹出 \\(j\\lt i-w\\)，队尾弹出不如新 \\(i-1\\) 的。每个下标进出一次，\\(O(n)\\)。\\(c[j]\\) 依赖 \\(j\\) 时键为 \\(dp[j]+c[j]\\)，同样单调队列若比较与 \\(i\\) 无关。</p><p><span class="marginnote">代入数字感受一下：\\(w=3\\)、键序列 \\([5, 3, 8]\\)。处理完前两个下标后队列里只剩键 3 那个（5 更老又更大，被尾弹）；8 虽然大但最新，留在队尾。求 \\(i=3\\) 时窗口是这三个，队头键 3 直接就是答案，一次比较没多用。</span></p><p>若决策 \\(j\\) 的优劣随 \\(i\\) 交叉（斜率），本课不够，下一课 CHT。</p><h3 id="不是优先队列" tabindex="-1">不是优先队列 <a class="header-anchor" href="#不是优先队列" aria-label="Permalink to &quot;不是优先队列&quot;">​</a></h3><p>优先队列给全局最值，删过期要惰性。窗口滑动用双端队列更干净。不要一上来堆。</p><p><span class="marginnote">双端队列（deque）就是两头都能进能出的队列：普通队列只能队尾进、队头出，deque 额外允许队头进、队尾出。单调队列两头都用到——头出「过期的」，尾出「被支配的」，这是普通队列或栈都凑不齐的能力组合。</span></p><p><span class="marginnote">滑动窗口最小值是经典。多重背包二进制/单调队列是应用。后课凸包维护与 \\(i\\) 相关的比较。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>递增下标队列。转移前弹头弹尾，取队头为最优 \\(j\\)。背包：容量滚动 + 余数分组队列。</p>',13)),(t(),B(r,null,{default:e(()=>[l(n,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20I%5B%22%E9%98%B6%E6%AE%B5%20i%22%5D%20--%3E%20POP%5B%22%E5%BC%B9%E8%BF%87%E6%9C%9F%E9%98%9F%E5%A4%B4%22%5D%0A%20%20POP%20--%3E%20TAIL%5B%22%E5%BC%B9%E4%B8%8D%E4%BC%98%E9%98%9F%E5%B0%BE%22%5D%0A%20%20TAIL%20--%3E%20HD%5B%22%E9%98%9F%E5%A4%B4%20%3D%20%E6%9C%80%E4%BC%98%20j%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[i(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("p",null,"键必须与队内比较无关 \\(i\\)，或随 \\(i\\) 同向移动。",-1)),a[4]||(a[4]=E("h2",{id:"机制",tabindex:"-1"},[i("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=E("p",null,"若 \\(j_1\\lt j_2\\) 且 \\(j_2\\) 不差于 \\(j_1\\)，则 \\(j_1\\) 永不再优，可从尾删。窗口左端单调，从头删。均摊线性。与树状数组：窗口最值也可用 ST 表 \\(O(1)\\)，但单调队列 \\(O(n)\\) 预处理零、在线友好。",-1)),(t(),B(r,null,{default:e(()=>[l(n,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20NEW%5B%22%E6%96%B0%E4%B8%8B%E6%A0%87%20i-1%20%E5%85%A5%E9%98%9F%22%5D%20--%3E%20CMP%5B%22%E4%B8%8E%E9%98%9F%E5%B0%BE%20j%20%E6%AF%94%E8%BE%83%22%5D%0A%20%20CMP%20--%3E%20WORSE%5B%22%E6%96%B0%E9%94%AE%E4%B8%8D%E4%BC%98%E4%BA%8E%20j%22%5D%0A%20%20WORSE%20--%3E%20KEEP%5B%22j%20%E7%95%99%E4%B8%8B%2C%20%E6%96%B0%E4%B8%8B%E6%A0%87%E8%BF%9B%E9%98%9F%E5%B0%BE%22%5D%0A%20%20CMP%20--%3E%20BETTER%5B%22%E6%96%B0%E9%94%AE%20%E2%89%A4%20%E9%98%9F%E5%B0%BE%20j%22%5D%0A%20%20BETTER%20--%3E%20DOM%5B%22j%20%E6%9B%B4%E8%80%81%E5%8F%88%E6%9B%B4%E5%B7%AE%3A%20%E8%A2%AB%E6%94%AF%E9%85%8D%22%5D%0A%20%20DOM%20--%3E%20POP2%5B%22%E4%BB%8E%E9%98%9F%E5%B0%BE%E5%BC%B9%E5%87%BA%20j%22%5D%0A%20%20POP2%20--%3E%20CMP2%5B%22%E5%86%8D%E7%9C%8B%E6%96%B0%E9%98%9F%E5%B0%BE%22%5D%0A%20%20CMP2%20--%3E%7C%22%E8%BF%98%E6%9C%89%E6%9B%B4%E5%B7%AE%E7%9A%84%22%7C%20POP2%0A%20%20CMP2%20--%3E%7C%22%E9%98%9F%E5%B7%B2%E5%8D%95%E8%B0%83%22%7C%20KEEP%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[i(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=o('<p><span class="marginnote">为什么队尾弹掉了也不用后悔：被弹的 \\(j\\) 比 新来的下标更老、键又不更小。窗口只会向右滑，老下标只会先过期，而只要新下标还在队里，\\(j\\) 就永远轮不到当最优——留着它纯属占内存。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写决策单调的分治（后课）。不写三维单调队列。后课默认：滑动窗口最值转移用单调队列。下一课斜率优化。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>窗口最值：双端队列均摊 \\(O(1)\\)。</li><li>决策交叉则换斜率/分治。</li><li>每个下标进出一次。</li><li>出处：滑动窗口与 Knuth 队列思想；CLRS DP。</li></ul>',5))])}const j=s(A,[["render",m]]);export{c as __pageData,j as default};
